package net.civeira.phylax.features.oauth.client.infrastructure.driver.rest;

import jakarta.enterprise.context.ApplicationScoped;
import net.civeira.phylax.features.oauth.oidc.domain.DiscoveryContributor;
import net.civeira.phylax.features.oauth.oidc.domain.OpenIdConfiguration;

/**
 * Contributes the dynamic client registration endpoint to the discovery document.
 */
@ApplicationScoped
public class ClientRegistrationContributor implements DiscoveryContributor {

  @Override
  public void contribute(OpenIdConfiguration.OpenIdConfigurationBuilder builder, String base) {
    builder.registrationEndpoint(base + "connect");
  }
}
